from pathlib import Path

ROOT=Path(__file__).parent/'web'
def page(kind,title,subtitle,roles,request,extra):
    hub='''<div class="hub">Coordinator · giao việc và giữ trạng thái</div><svg class="wires" viewBox="0 0 1000 25" preserveAspectRatio="none" aria-hidden="true"><path d="M500 0V10H125V25 M500 10H375V25 M500 10H625V25 M500 10H875V25"/></svg>''' if kind=='hub' else ''
    settings='''<details class="settings"><summary>Yêu cầu và cấu hình phiên</summary><div class="setting-box"><label class="field" for="request">Mô tả yêu cầu</label><textarea id="request" rows="5">'''+request+'''</textarea>'''+extra+'''<p id="scope"></p></div></details>'''
    html='''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'''+title+'''</title><link rel="stylesheet" href="/assets/style.css"><script defer src="/assets/app.js"></script></head><body data-kind="'''+kind+'''"><header><div class="brand"><div class="brand-icon">'''+('H' if kind=='hub' else 'N')+'''</div><div><b>'''+title+'''</b><small>Gemini API + bộ kiểm tra Python thực</small></div></div><span class="badge" id="connection">Đang kiểm tra cấu hình…</span></header><main><h1>'''+subtitle+'''</h1><p class="lead" id="lead"></p>'''+settings+'''<details class="settings"><summary>Kết nối Gemini / hướng dẫn cấu hình</summary><div class="setting-box"><p id="config-text"></p><p>Chạy <b>cau-hinh-api.cmd</b> hoặc <b>python setup_api.py</b> trong thư mục <b>NLTS/real-demo</b>. Key chỉ lưu vào .env trên máy.</p><a href="https://aistudio.google.com/apikey" target="_blank" rel="noopener">Tạo key trong Google AI Studio ↗</a><p>Chọn project Free Tier nếu muốn dùng hạn mức miễn phí. Hệ thống không xác định được tài khoản đã bật thanh toán hay chưa.</p></div></details><section class="panel"><div class="panel-title">'''+('Luồng điều phối' if kind=='hub' else 'Quy trình MANS')+'''</div>'''+hub+'''<div class="agents">'''+''.join('<div class="agent">'+r+'</div>' for r in roles)+'''</div><div id="status" class="status" aria-live="polite"></div><div class="output" id="output"></div><p class="error-text" id="error" role="alert"></p><div class="toolbar"><button id="next">Bắt đầu</button><a href="#" id="reset">Bắt đầu lại</a></div></section><details class="history"><summary>Lịch sử và dữ liệu của phiên</summary><div class="log-box"><div id="history"></div><p id="usage" class="subtle"></p><a class="inline-link" href="#" id="export">Tải kết quả phiên JSON</a></div></details>'''+('''<details class="settings"><summary>Kiểm tra AST / QA trực tiếp, không gọi API</summary><div class="setting-box"><p>Dán đoạn Python có đúng một hàm validate_email(email). Kiểm tra bằng quy tắc và bộ thông dịch AST giới hạn, không chạy Python tùy ý.</p><textarea class="code" id="gate-code" rows="8"></textarea><a href="#" class="inline-link" id="sample-gate">Điền mã mẫu có secret</a><br><button id="gate-run">Kiểm tra mã</button><div id="gate-result" class="gate-result"></div></div></details>''' if kind=='hub' else '')+'''<p class="note" id="note"></p></main></body></html>'''
    (ROOT/(kind+'.html')).write_text(html,encoding='utf-8')

page('hub','Hub-and-Spoke Workspace','Từ yêu cầu đến mã đã qua kiểm tra',['Story Planner','Developer','QA','Governance'],
     'Viết hàm Python validate_email(email) để kiểm tra email đăng nhập sinh viên. Bỏ khoảng trắng ở hai đầu; email cần đúng một @, phần trước @ không rỗng, tên miền có dấu chấm và không có khoảng trắng bên trong. Không viết cứng secret trong mã.',
     '<label class="field" for="initial-code">Mã có sẵn để kiểm tra (tùy chọn; bỏ trống để Gemini viết)</label><textarea class="code" id="initial-code" rows="5" placeholder="Dán mã Python của bạn hoặc dùng ví dụ bên dưới"></textarea><a class="inline-link" href="#" id="sample-code">Điền ví dụ có secret để thử cổng Governance</a>')
page('mans','NL2Schedule / MANS','Lập lịch từ mô tả công việc',['Seeker','Weaver','Verifier','Architect'],
     'Cần làm hai sản phẩm A và B. A phải cắt 3 phút rồi sơn 2 phút. B phải cắt 2 phút rồi sơn 4 phút. Có một máy Cắt và một máy Sơn, mỗi máy làm một công đoạn tại một thời điểm. Không được ngắt công đoạn. Hãy sắp xếp để hoàn thành cả hai sản phẩm sớm nhất.', '')
print('Built real Hub/MANS web pages.')
